  function parseCsv(text) { const lines = text.replace(/^\uFEFF/, "").split(/\r?\n/).filter((line) => line.trim()); const cells = lines.map((line) => { const result = []; let current = ""; let quoted = false; for (let i = 0; i < line.length; i += 1) { const char = line[i]; if (char === '"' && line[i + 1] === '"') { current += '"'; i += 1; } else if (char === '"') quoted = !quoted; else if (char === "," && !quoted) { result.push(current); current = ""; } else current += char; } result.push(current); return result; }); const headers = (cells.shift() || []).map((header) => String(header).trim()); return { headers, rows: cells.map((row) => Object.fromEntries(headers.map((header, index) => [header, row[index] || ""]))) }; }
  function fileToRows(file) { return new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => { try { if (/\.csv$/i.test(file.name)) { const text = typeof reader.result === "string" ? reader.result : new TextDecoder("utf-8").decode(reader.result); resolve(parseCsv(text)); } else if (window.XLSX) { const wb = window.XLSX.read(reader.result, { type: "array" }); const sheet = wb.Sheets[wb.SheetNames[0]]; resolve(normalizeRows(window.XLSX.utils.sheet_to_json(sheet, { defval: "" }))); } else reject(new Error("当前未加载 Excel 解析器，请改用 CSV")); } catch (error) { reject(error); } }; reader.onerror = () => reject(reader.error); reader.readAsArrayBuffer(file); }); }
