  function numberValue(value) { if (typeof value === "number") return Number.isFinite(value) ? value : null; const text = textValue(value).replace(/[￥¥,\s]/g, ""); if (!text) return null; const parsed = Number(text); return Number.isFinite(parsed) ? parsed : null; }
