  function categoryValue(value) { return ({ "销售回款": "销售收款", "销售收款": "销售收款", "贷款": "贷款", "注资": "注资", "内部转账": "内部转账", "退款": "退款", "采购付款": "采购付款" })[textValue(value)] || "待复核"; }
  function mapImportRow(type, row) { if (type === "bank") return { id: textValue(row["业务单号"]), date: dateValue(row["交易日期"]), subject: textValue(row["对方名称"]), summary: textValue(row["摘要"]), in: numberValue(row["入账金额"]) ?? 0, out: numberValue(row["出账金额"]) ?? 0, balance: numberValue(row["余额"]) ?? 0, category: categoryValue(row["分类"]), link: textValue(row["业务单号"]) }; if (type === "statement") return { id: textValue(row["银行流水号"]), date: dateValue(row["交易日期"]), subject: textValue(row["对方名称"]), summary: textValue(row["摘要"]), in: numberValue(row["收入金额"]) ?? 0, out: numberValue(row["支出金额"]) ?? 0, balance: numberValue(row["银行余额"]) ?? 0, link: textValue(row["业务单号"]), verified: false }; if (type === "sales") return { no: textValue(row["业务单号"]), date: dateValue(row["销售日期"]), customer: textValue(row["客户名称"]), due: dateValue(row["到期日"]), total: numberValue(row["含税金额"]) ?? 0, paid: 0 }; if (type === "purchase") return { no: textValue(row["业务单号"]), date: dateValue(row["采购日期"]), supplier: textValue(row["供应商名称"]), due: dateValue(row["到期日"]), total: numberValue(row["含税金额"]) ?? 0, paid: 0 }; if (type === "expense") return { no: textValue(row["报销单号"]), submitDate: dateValue(row["提交日期"]), employeeId: textValue(row["员工编号"]), employee: textValue(row["员工姓名"]), department: textValue(row["部门"]), expenseDate: dateValue(row["费用日期"]), category: textValue(row["费用类别"]), description: textValue(row["费用说明"]), payee: textValue(row["收款方"]), amount: numberValue(row["报销金额"]) ?? 0, taxAmount: numberValue(row["税额"]) ?? 0, invoiceNo: textValue(row["发票号码"]), authenticity: textValue(row["真实性"]) || "待核实", invoiceStatus: textValue(row["发票合规"]) || "待补票", approvalStatus: textValue(row["审批状态"]) || "待审批", approvedDate: dateValue(row["审批完成日"]), paymentDate: dateValue(row["付款日期"]), paymentStatus: textValue(row["付款状态"]) || "未安排", budgetCategory: textValue(row["预算科目"]) || textValue(row["费用类别"]), budget: numberValue(row["预算金额"]) ?? 0, accountingStatus: textValue(row["账务处理状态"]) || "未处理" }; if (type === "fixedAsset") return { no: textValue(row["资产编号"]), name: textValue(row["资产名称"]), category: textValue(row["资产类别"]), purchaseDate: dateValue(row["购置日期"]), cost: numberValue(row["原值"]) ?? 0, salvage: numberValue(row["残值"]) ?? 0, months: numberValue(row["使用年限(月)"]) ?? 36, method: textValue(row["折旧方法"]) || "直线法", accumulated: numberValue(row["累计折旧"]) ?? 0, status: textValue(row["状态"]) || "使用中", owner: textValue(row["责任人"]), lastDepreciationMonth: "" }; if (type === "invoice") return { no: textValue(row["发票号码"]), type: textValue(row["发票类型"]) || "普通发票", date: dateValue(row["开票日期"]), seller: textValue(row["销方名称"]), amount: numberValue(row["含税金额"]) ?? 0, tax: numberValue(row["税额"]) ?? 0, rate: (numberValue(row["税率"]) ?? 0) / 100, verifyStatus: textValue(row["查验状态"]) || "待查验", certifyStatus: textValue(row["认证状态"]) || "待认证", linkExpense: textValue(row["关联报销单号"]) }; if (type === "payroll") { const month = textValue(row["工资月份"]); const employeeId = textValue(row["员工编号"]); return { id: `${month}-${employeeId}`, month, employeeId, employee: textValue(row["员工姓名"]), department: textValue(row["部门"]), gross: numberValue(row["应发工资"]) ?? 0, socialBase: numberValue(row["社保基数"]) ?? 0, fundBase: numberValue(row["公积金基数"]) ?? 0, tax: numberValue(row["个税"]) ?? 0, otherDeduction: numberValue(row["其他扣款"]) ?? 0, payDate: dateValue(row["发薪日"]), taxDate: dateValue(row["个税缴款日"]), contributionDate: dateValue(row["社保公积金缴费日"]) }; } return { no: textValue(row["付款单号"]), link: textValue(row["业务单号"]), date: dateValue(row["付款日期"]), supplier: textValue(row["供应商名称"]), amount: numberValue(row["付款金额"]) ?? 0 }; }

