  function syncReconciliations() { const payments = new Map(); state.payments.forEach((payment) => { if (payment.link) payments.set(payment.link, (payments.get(payment.link) || 0) + Number(payment.amount || 0)); }); state.purchases.forEach((purchase) => { purchase.paid = Math.min(Number(purchase.total || 0), payments.get(purchase.no) || 0); }); const receipts = new Map(); state.bank.filter((row) => row.category === "销售收款").forEach((row) => { if (row.link) receipts.set(row.link, (receipts.get(row.link) || 0) + Number(row.in || 0)); }); state.sales.forEach((sale) => { sale.paid = Math.min(Number(sale.total || 0), receipts.get(sale.no) || 0); }); }
